eturn Number(c.dataset.methodId)});fetch("{{ route('payment-methods.reorder') }}",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-TOKEN":"{{ csrf_token() }}","Accept":"application/json"},body:JSON.stringify({order:order})}).then(function(r){return r.json()}).then(function(d){saveOrder.textContent=d.message})};var templates={cod:{name:'Cash on Delivery',code:'cash_on_delivery',method_type:'cash_on_delivery',customer_label:'Cash on Delivery',short_instruction:'Pay in cash when your order is delivered.',integration_mode:'offline',provider:'Cash'},bkash:{name:'bKash Manual Payment',code:'bkash_manual',method_type:'mobile_financial_service',customer_label:'Pay with bKash',short_instruction:'Send the payable amount to the displayed merchant number and enter the Transaction ID.',integration_mode:'manual',provider:'bKash'},nagad:{name:'Nagad Manual Payment',code:'nagad_manual',method_type:'mobile_financial_service',customer_label:'Pay with Nagad',short_instruction:'Send the payable amount to the displayed merchant number and enter the Transaction ID.',integration_mode:'manual',provider:'Nagad'},bank:{name:'Bank Transfer',code:'bank_transfer',method_type:'bank_transfer',customer_label:'Bank Transfer',short_instruction:'Transfer the payable amount and submit the payment reference.',integration_mode:'manual',provider:'Bank'},gateway:{name:'Online Payment',code:'online_gateway',method_type:'payment_gateway',customer_label:'Pay Online',short_instruction:'Complete payment on the secure hosted gateway page.',integration_mode:'hosted_checkout',provider:'SSLCOMMERZ'}};document.querySelectorAll('[data-template]').forEach(function(b){b.onclick=function(){var d=templates[this.dataset.template],f=add.querySelector('form');Object.keys(d).forEach(function(k){var x=f.querySelector('[name="'+k+'"]');if(x)x.value=d[k]});add.open=true}})}());</script>
